declare const tools: { mcp__holdspeak__project_item_create(args: {
  // Optional idempotency key. The same key with the same arguments returns the first result again; the same key with different arguments is refused with idempotency_conflict.
  command_id?: string;
  // Optional, closed per item type (unknown fields are refused): milestone {completion_evidence_refs}; risk {likelihood, impact, mitigation} (likelihood and impact required); dependency {direction: upstream|downstream, counterpart_ref, required_by, confidence}; signal {metric, unit, latest_value, source_ref, observed_at}; workstream {}.
  details?: { [key: string]: unknown; } | null;
  // Optional date, ISO 8601 (for a milestone: when it is due).
  due_at?: string | null;
  // Optional. The project revision from your last read (project.get or project.get_room, field revision). When the current revision differs, the call is refused with stale_revision and nothing changes.
  expected_revision?: number;
  // milestone, risk, dependency, signal or workstream.
  item_type: "milestone" | "risk" | "dependency" | "signal" | "workstream";
  // Optional start state in the type's set; default planned (milestone), open (risk), healthy, active, active.
  lifecycle?: "planned" | "reached" | "missed" | "dropped" | "open" | "mitigated" | "accepted" | "closed" | "healthy" | "at_risk" | "broken" | "resolved" | "active" | "retired" | "paused" | "done";
  // Optional owner, as kind:id (for example person:<id>).
  owner_ref?: string | null;
  // The project id: projects[].id from project.list, or project.id from project.create.
  project_id: string;
  // Optional: critical, high, medium or low.
  severity?: "critical" | "high" | "medium" | "low" | null;
  // Optional number for ordering.
  sort_key?: number | null;
  // Optional text.
  summary?: string | null;
  // The item's title (required, not empty).
  title: string;
}): Promise<CallToolResult>; };
